package sudoku;
import java.nio.file.*;
import java.util.*;
import javax.swing.*;
/** Empty and malformed frame states fail visibly without exposing the live board. */
public final class ReplayViewerEdgeProbe {
 public static void main(String[] args)throws Exception{System.setProperty("hodoku.data.dir",Files.createTempDirectory("replay-viewer-edge-").toString());try{SwingUtilities.invokeAndWait(()->{MainFrame f=new MainFrame(null);try{ReplayController c=f.getReplayController();ReplayBoard before=new ReplayBoard(f.getSudokuPanel().getSudoku());ReplayViewer empty=new ReplayViewer(c,new ReplaySession("empty",1));if(empty.selectedFrame()!=null||empty.boardPanel().isVisible())throw new AssertionError("empty state");empty.disposeViewer();ReplaySession unsafe=new ReplaySession(before,1);String html="<html><img src='file:/nonexistent/replay-test'>literal";unsafe.addBookmark(new ReplayBookmark(0,html,1,0));ReplayViewer literal=new ReplayViewer(c,unsafe);try{java.lang.reflect.Field bf=ReplayViewer.class.getDeclaredField("bookmarks");bf.setAccessible(true);JComboBox combo=(JComboBox)bf.get(literal);JLabel rendered=(JLabel)combo.getRenderer().getListCellRendererComponent(new JList(),html,1,false,false);if(!html.equals(rendered.getText())||rendered.getClientProperty(javax.swing.plaf.basic.BasicHTML.propertyKey)!=null)throw new AssertionError("bookmark interpreted as HTML");literal.disposeViewer();}catch(Exception ex){throw new RuntimeException(ex);}ReplaySession bad=new ReplaySession(before,1);bad.append(Collections.singletonList(new ReplayFrame(1,2,1,"proof","bad evidence",before,new byte[]{1,2,3})));ReplayViewer error=new ReplayViewer(c,bad);error.showFrame(1);if(error.boardPanel().isVisible())throw new AssertionError("invalid proof showed stale board");if(!new ReplayBoard(f.getSudokuPanel().getSudoku()).equals(before))throw new AssertionError("error changed live board");error.disposeViewer();System.out.println("Empty and malformed replay frames handled without live mutation");}finally{f.dispose();}});}catch(Throwable e){e.printStackTrace();System.exit(1);}System.exit(0);}
}
